import asyncio
from functools import partial

class Client:
    async def fetch(self, url: str) -> str: ...

    def fetch_then(self, url: str, session: "Session") -> None:
        task = asyncio.create_task(self.fetch(url))
        task.add_done_callback(partial(session.store, url))   # context bound by partial

    def schedule(self, delay: float, callback) -> None:
        asyncio.get_running_loop().call_later(delay, callback)  # loop thread, no frame kept
